class Solution:
    def alternatingXorPartitions(self, nums, target1, target2):
        MOD = 10**9 + 7
        n = len(nums)
        P = [0]*(n+1)
        for i, x in enumerate(nums):
            P[i+1] = P[i] ^ x
        dp0 = [0]*(n+1)
        dp1 = [0]*(n+1)
        dp0[0] = 1
        for i in range(1, n+1):
            for j in range(i):
                d = P[i] ^ P[j]
                if d == target1:
                    dp1[i] = (dp1[i] + dp0[j]) % MOD
                elif d == target2:
                    dp0[i] = (dp0[i] + dp1[j]) % MOD
        return dp0[n]

