class Solution {
public:
    int alternatingXorPartitions(vector<int>& nums, int target1, int target2) {
        const long long MOD = 1e9 + 7;
        unordered_map<int, long long> even{{0, 1}}, odd;
        int p = 0;
        for (int x : nums) {
            p ^= x;
            long long ne = 0, no = 0;
            auto it = odd.find(p ^ target2); if (it != odd.end()) ne = it->second;
            auto it2 = even.find(p ^ target1); if (it2 != even.end()) no = it2->second;
            even[p] = (even[p] + ne) % MOD;
            odd[p] = (odd[p] + no) % MOD;
        }
        auto it = even.find(p);
        return it == even.end() ? 0 : (int) it->second;
    }
};

