class Solution {
    public int alternatingXorPartitions(int[] nums, int target1, int target2) {
        final long MOD = 1_000_000_007L;
        Map<Integer, Long> even = new HashMap<>(), odd = new HashMap<>();
        even.put(0, 1L);
        int p = 0;
        for (int x : nums) {
            p ^= x;
            long ne = odd.getOrDefault(p ^ target2, 0L);
            long no = even.getOrDefault(p ^ target1, 0L);
            even.merge(p, ne, Long::sum);
            odd.merge(p, no, Long::sum);
            even.put(p, even.get(p) % MOD);
            odd.put(p, odd.get(p) % MOD);
        }
        return even.getOrDefault(p, 0L).intValue();
    }
}

